fn get_min_val(a: &Vec<i8>) -> i8 {
    *a.iter().min().unwrap() // Get the minimum value from the array
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    *a.iter().max().unwrap() // Get the maximum value from the array
}

fn nanquantile(a: Vec<i8>, q: i8) -> i8 {
    let n = a.len();
    let sorted_a: Vec<i8> = {
        let mut temp = a.clone();
        temp.sort();
        temp
    };

    if q == 0 {
        return get_min_val(&sorted_a);
    } else if q == 100 {
        return get_max_val(&sorted_a);
    }

    // Calculate the index for the quantile
    let index = ((q as f64 / 100.0) * (n as f64 - 1.0)).round() as usize;
    sorted_a[index]
}

fn main() {
    let data = vec![3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5];
    let q0 = nanquantile(data.clone(), 0);
    let q50 = nanquantile(data.clone(), 50);
    let q100 = nanquantile(data.clone(), 100);

    println!("Quantile 0: {}", q0);   // Should print the minimum value
    println!("Quantile 50: {}", q50); // Should print the median value
    println!("Quantile 100: {}", q100); // Should print the maximum value
}